#include <QCoreApplication>
#include <QFile>
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <QSet>
static QJsonObject read(const QString &path){QFile f(path);if(!f.open(QIODevice::ReadOnly))qFatal("Input missing");return QJsonDocument::fromJson(f.readAll()).object();}
static QSet<int> values(const QJsonArray &array){QSet<int> set;for(auto v:array)set.insert(v.toInt());return set;}
int main(int argc,char **argv){QCoreApplication app(argc,argv);if(argc!=3)return 2;QString root=argv[1];auto semantics=read(root+"/native-otp-semantics.json"),graphemes=read(root+"/native-otp-graphemes.json"),properties=read(root+"/numeric-cluster-properties.json");auto numbers=values(semantics.value("singleScalarNumbers").toArray()),joining=values(properties.value("joiningScalars").toArray()),prepend=values(properties.value("prependScalars").toArray());
 auto filter=[&](const QJsonArray &input,int limit){QJsonArray result;int count=0;bool retaining=false,previousPrepend=false;for(auto value:input){const int scalar=value.toInt();if(numbers.contains(scalar) && !previousPrepend){retaining=limit<0 || count<limit;if(retaining)++count;}else if(!joining.contains(scalar))retaining=false;if(retaining)result.append(value);previousPrepend=prepend.contains(scalar);}return result;};
 QJsonArray examples,contexts,vectors;int exampleMatches=0,contextMatches=0,vectorMatches=0;
 for(auto v:semantics.value("examples").toArray()){auto r=v.toObject();auto input=r.value("input").toObject().value("scalars").toArray();auto actual=filter(input,r.value("length").toInt());bool match=actual==r.value("result").toObject().value("scalars").toArray();exampleMatches+=match;examples.append(QJsonObject{{"case",r.value("case")},{"length",r.value("length")},{"scalars",actual},{"matchesNative",match}});}
 for(auto v:graphemes.value("markContexts").toArray()){auto r=v.toObject();QJsonArray input{r.value("base"),r.value("mark"),50};auto all=filter(input,-1),one=filter(input,1);bool match=all==r.value("filteredScalars").toArray() && one==r.value("prefixOneScalars").toArray();contextMatches+=match;contexts.append(QJsonObject{{"base",r.value("base")},{"mark",r.value("mark")},{"scalars",all},{"prefixOneScalars",one},{"matchesNative",match}});}
 for(auto v:graphemes.value("officialTests").toArray()){auto r=v.toObject();auto actual=filter(r.value("scalars").toArray(),-1);bool match=actual==r.value("filteredScalars").toArray();vectorMatches+=match;vectors.append(QJsonObject{{"index",r.value("index")},{"scalars",actual},{"matchesNative",match}});}
 QJsonObject result{{"reference",semantics.value("reference")},{"qt",qVersion()},{"scope","Standalone C++ projection of the exact OTP filter/prefix using source numeric scalars and Unicode17 joining/prepend facts; no production control or generic grapheme implementation"},{"examples",examples},{"markContexts",contexts},{"graphemeVectorFilters",vectors},{"summary",QJsonObject{{"examples",examples.size()},{"matchingExamples",exampleMatches},{"markContexts",contexts.size()},{"matchingMarkContexts",contextMatches},{"graphemeVectors",vectors.size()},{"matchingGraphemeVectorFilters",vectorMatches}}}};QFile output(argv[2]);if(!output.open(QIODevice::WriteOnly))return 3;output.write(QJsonDocument(result).toJson());qInfo().noquote()<<QJsonDocument(result.value("summary").toObject()).toJson();return exampleMatches==examples.size() && contextMatches==contexts.size() && vectorMatches==vectors.size() ? 0:1;}
